const rawQuery = String($('Tool input').first().json.query || '').toLowerCase();
const L = '[а-яіїєґ’\']*';
const aliases = [
  ['нью\\s*бал' + L + '|нью\\s*бел' + L + '|ньюбал' + L + '|ньюбел' + L + '|нб(?:еш' + L + ')?|нбешк' + L + '|nb', 'new balance'],
  ['ад[іи]к' + L + '|ад[іи]д' + L + '|адд[іи]д' + L, 'adidas'],
  ['пум' + L, 'puma'],
  ['р[іие]б[оу]к' + L, 'reebok'],
  ['найк' + L, 'nike'],
  ['ас[іи]кс' + L, 'asics'],
  ['конверс' + L, 'converse'],
  ['ванс' + L, 'vans'],
  ['скечерс' + L + '|скетчерс' + L, 'skechers'],
  ['салом[оа]н' + L + '|солом[оа]н' + L, 'salomon'],
  ['т[іи]мберл' + L + '|т[іи]мб' + L, 'timberland'],
  ['тнф|tnf|(?:зе\\s*)?норт\\s*фейс' + L + '|нортфейс' + L, 'the north face'],
  ['колумб[іи]' + L + '|коламб[іи]' + L, 'columbia'],
  ['джордан' + L, 'jordan'],
  ['філ[аиі]', 'fila'],
  ['крокс' + L, 'crocs'],
  ['угг' + L + '|уґґ' + L + '|угі', 'ugg'],
  ['мартен' + L + '|мартін' + L + '|мартинс' + L, 'dr martens'],
  ['(?:ундер|андер)\\s*армор' + L, 'under armour'],
  ['хок[аи]|гок[аи]', 'hoka'],
  ['сокані|саукон' + L, 'saucony'],
  ['мерр?ел' + L, 'merrell'],
  ['лакост' + L, 'lacoste'],
  ['баленс[іи]аг' + L, 'balenciaga'],
  ['гучч?і', 'gucci'],
  ['єзі|ізі|їзі', 'yeezy'],
  ['м[іи]цуно|мізуно', 'mizuno'],
  ['афі?1|афк' + L + '|(?:ейр|аір|айр)\\s*форс' + L + '|форс(?:и|ах)', 'air force'],
  ['данк' + L, 'dunk'],
  ['(?:ейр|аір|айр)\\s*макс' + L + '|макси', 'air max'],
  ['самб[аиуі]' + L, 'samba'],
  ['газел' + L, 'gazelle'],
  ['кампус' + L, 'campus'],
  ['стан\\s*сміт' + L + '|стен\\s*сміт' + L, 'stan smith'],
  ['суперстар' + L, 'superstar'],
  ['асг|ацг', 'acg'],
  ['чобот' + L + '|черевик' + L + '|б[оа]тинк' + L + '|ботінк' + L + '|сапог' + L, 'boot']
];
let q = rawQuery;
for (const [pat, target] of aliases) {
  q = q.replace(new RegExp('(^|[^а-яіїєґa-z0-9])(?:' + pat + ')(?![а-яіїєґa-z0-9])', 'g'), '$1' + target);
}
const winterWord = /^(зим|тепл|утепл|мороз|холод|сніг|слякот|хутр|мех|термо|дощ|водостій|водонепро|непромок|осін|осен|winter|waterproof)/;
const winterIntent = q.split(/[^a-zа-яіїєґ0-9]+/i).some(t => winterWord.test(t));

const gtx = /gore|гортекс|гор-текс|gortex|goretex|гортех|гортек/.test(q);
const colorDefs = [
  [/чорн|черн|black/, ['black']],
  [/біл|бел|white/, ['white']],
  [/сір|сер|grey|gray/, ['grey', 'gray']],
  [/коричн|brown/, ['brown']],
  [/беж|beige|cream|крем/, ['beige', 'cream', 'muslin', 'cave stone']],
  [/зелен|green/, ['green']],
  [/син|blue|navy/, ['blue', 'navy']],
  [/червон|red/, ['red']],
  [/рожев|pink/, ['pink']],
  [/жовт|yellow/, ['yellow']],
  [/хакі|khaki|оливк|olive/, ['khaki', 'olive']],
  [/срібл|silver/, ['silver']]
];
const colorAlts = [];
for (const [re, alts] of colorDefs) if (re.test(q)) colorAlts.push(alts);
const sizeM = q.match(/(?<![0-9,.])(3[4-9]|4[0-9])(?![0-9])/);
const wantSize = sizeM ? sizeM[1] : null;

const stop = ['на','хутрі','хутро','розмір','є','для','the','size','model_id','modelid','gore','tex','gore-tex','goretex','gortex','гортекс','гор','текс','будь','який','що','вітаю','привіт','добрий','день','вечір','здрастуйте','підкажіть','підкажи','покажіть','покажи','порадьте','порадь','мені','можна','яке','які','щось','якесь','ласка','мене','цікавить','шукаю','хочу','потрібні','потрібно','вас','чи','або','та','кросівки','кросівок','кросовки','взуття','обувь','кеди','пару','модель','моделі'];
const colorWords = /^(чорн|черн|black|біл|бел|white|сір|сер|grey|gray|коричн|brown|беж|beige|зелен|green|син|blue|navy|червон|red|рожев|pink|жовт|yellow|хакі|khaki|оливк|olive|срібл|silver)/;
const tokens = q.split(/[^a-zа-яіїєґ0-9]+/i).filter(t => t.length > 1 && !/^(3[4-9]|4[0-9])$/.test(t) && !stop.includes(t) && !colorWords.test(t) && !winterWord.test(t));

const all = $input.all().map(i => i.json).filter(r => r.model);
const lower = (r) => String(r.model).toLowerCase();
const score = (r) => tokens.filter(t => lower(r).includes(t)).length;
const idm = rawQuery.match(/(?<![0-9])([0-9]{4,7})(?![0-9])/);
const byId = idm ? all.find(r => String(r.group_id) === idm[1]) : null;
const hasSize = (r, s) => new RegExp('(^|, )' + s + ' \\(').test(String(r.sizes_in_stock || ''));
const isGtx = (r) => /gore[\s-]*tex/i.test(r.model);
const isWinter = (r) => /fur|мех|хутр|boot|ботин|чобіт|gore[\s-]*tex|cordura|winter|утепл|зим|термо|ugg|timberland/i.test(String(r.model) + ' ' + String(r.description || ''));
const hasColor = (r) => colorAlts.every(alts => alts.some(a => lower(r).includes(a)));

let found = [];
let mode = '';
let note = '';
if (byId) {
  found = [byId]; mode = 'точний збіг за model_id';
} else {
  let base = tokens.length ? all.filter(r => score(r) === tokens.length) : all.slice();
  if (tokens.length && !base.length) base = all.filter(r => score(r) > 0);
  const filterLabel = [winterIntent ? 'зимові/водостійкі (за назвою: хутро, boots, Gore-Tex, Cordura)' : '', gtx ? 'Gore-Tex' : '', colorAlts.length ? 'колір за назвою' : '', wantSize ? 'розмір ' + wantSize + ' є в наявності' : ''].filter(Boolean).join(', ');
  const strict = (r) => (!gtx || isGtx(r)) && (!winterIntent || isWinter(r)) && hasColor(r) && (!wantSize || hasSize(r, wantSize)) && ((!gtx && !colorAlts.length && !wantSize && !winterIntent) || r.in_stock_count > 0);
  found = base.filter(strict);
  mode = filterLabel ? 'фільтри: ' + filterLabel : 'усі слова збіглися';
  if (!found.length && filterLabel) {
    if (wantSize) {
      const r1 = base.filter(r => (!gtx || isGtx(r)) && (!winterIntent || isWinter(r)) && hasColor(r) && r.in_stock_count > 0);
      if (r1.length) { found = r1; note = 'Точного збігу з розміром ' + wantSize + ' НЕМАЄ. Нижче моделі з тими ж критеріями, які є в ІНШИХ розмірах.'; }
    }
    if (!found.length && colorAlts.length) {
      const r2 = base.filter(r => (!gtx || isGtx(r)) && (!winterIntent || isWinter(r)) && (!wantSize || hasSize(r, wantSize)) && r.in_stock_count > 0);
      if (r2.length) { found = r2; note = 'Точного збігу за кольором НЕМАЄ. Нижче ті ж моделі інших кольорів' + (wantSize ? ' у розмірі ' + wantSize : '') + '.'; }
    }
    if (!found.length && gtx) {
      const r3 = all.filter(r => isGtx(r) && (!wantSize || hasSize(r, wantSize)) && r.in_stock_count > 0);
      if (r3.length) { found = r3; note = 'У цьому бренді/кольорі нічого немає. Нижче всі моделі Gore-Tex у каталозі' + (wantSize ? ' у розмірі ' + wantSize : '') + ', усіх брендів.'; }
    }
    if (!found.length && winterIntent && tokens.length) {
      const r4 = all.filter(r => isWinter(r) && (!wantSize || hasSize(r, wantSize)) && r.in_stock_count > 0);
      if (r4.length) { found = r4; note = 'У цьому бренді зимових моделей НЕМАЄ. Нижче зимові/водостійкі моделі інших брендів' + (wantSize ? ' у розмірі ' + wantSize : '') + '.'; }
    }
    if (!found.length) note = 'За цими фільтрами моделей в наявності НЕМАЄ (перевірено весь каталог).';
  }
  if (winterIntent && found.length) note = (note ? note + ' ' : '') + 'У каталозі немає окремого поля "сезон", тому моделі підібрані за назвою та матеріалом: Fur/хутро/мех і boots = утеплені, Gore-Tex = водостійка мембрана, Cordura = міцний текстиль (не обов\'язково утеплений). Це чесна підстава пропонувати їх на зиму; для точних характеристик конкретної моделі можна знайти опис в інтернеті.';
}
found.sort((a, b) => (score(b) - score(a)) || ((wantSize && hasSize(b, wantSize) ? 1 : 0) - (wantSize && hasSize(a, wantSize) ? 1 : 0)) || ((b.in_stock_count || 0) - (a.in_stock_count || 0)));
const top = found.slice(0, 8);
const complete = found.length <= top.length;

const material = (r) => String(r.description || '').replace(/Виробник\s*:.*$/i, '').replace(/Матеріал\s*:/i, '').trim();
const fmt = (r) => {
  const mat = material(r);
  const warm = /хутр|мех|утепл|зим|fur|winter/i.test(r.model + ' ' + (r.description || ''));
  return r.model + ' [model_id ' + r.group_id + '] | ' + r.price + ' грн | є розміри: ' + (r.sizes_in_stock ? r.sizes_in_stock : 'немає в наявності') + (r.sizes_out ? ' | немає розмірів: ' + r.sizes_out : '') + ' | матеріал у каталозі: ' + (mat || 'не вказано') + (isGtx(r) ? ' | у назві Gore-Tex (водостійка мембрана)' : '') + (warm ? ' | у каталозі є позначка про утеплення/зиму' : '');
};

const rule = '\nПРАВИЛО: пропонуй клієнту ТІЛЬКИ моделі з цього списку, нічого не вигадуй. ' + (complete ? 'Цей список ПОВНИЙ: усі моделі каталогу, що відповідають запиту (перевірено весь каталог), тому впевнено говори, що інших немає, і НЕ передавай менеджеру через список. ' : 'Цей список НЕПОВНИЙ (показано лише частину): твердити, що інших моделей немає, не можна; запропонуй клієнту уточнити запит (бренд, колір, розмір). ') + 'Якщо клієнт назвав розмір, він вже врахований у фільтрі. Якщо точного збігу немає — чесно скажи про це і запропонуй найближчі варіанти з списку (інший розмір, інший колір).\nХАРАКТЕРИСТИКИ (сезон, утеплення, водостійкість, технології, призначення): матеріал каталогу називай як є, Gore-Tex у назві означає водостійку мембрану. Якщо даних мало, шукай опис моделі в інтернеті (з позначкою джерела) та НЕ викликай handoff_to_human без згоди клієнта.' + (winterIntent ? '\nКлієнт питає про зимові/теплі моделі: НЕ передавай менеджеру. Запропонуй 2–3 моделі зі списку (різні типи, наприклад чоботи з хутром і Gore-Tex), поясни чому вони підходять на зиму і уточни стать, розмір, бренд чи бюджет.' : '');

const result = top.length
  ? 'Знайдено моделей: ' + found.length + ' (' + mode + '). Показано ' + top.length + (complete ? ' (усі)' : ' найбільш підхожих') + ':' + (note ? '\n' + note : '') + '\n' + top.map(fmt).join('\n') + rule
  : (note ? note + ' ' : '') + 'За запитом "' + rawQuery + '" у каталозі нічого не знайдено. Усього моделей у каталозі: ' + all.length + '. Попроси клієнта уточнити назву моделі і нічого не вигадуй.';

return [{ json: { result } }];
